css:
@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@300;700&display=swap');

:root { 
  --bg-main: #0a0a0a; 
  --bg-card: #161616; 
  --bg-header: #0a0a0a; 
  --accent: #00ff9d; 
  --text-main: #ffffff; 
  --text-gray: #a3a3a3; 
  --border-color: #333333; 
  --font-main: 'Space Grotesk', sans-serif; 
  --font-heading: 'Space Grotesk', sans-serif; 
  --shadow-sm: 0 0 20px rgba(0, 255, 157, 0.1); 
  --radius: 16px; 
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body { 
  font-family: var(--font-main); 
  background-color: var(--bg-main); 
  color: var(--text-gray); 
  line-height: 1.6; 
  display: flex; 
  flex-direction: column; 
  min-height: 100vh; 
  letter-spacing: -0.02em;
}

a { text-decoration: none; color: inherit; transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1); }

a:hover { color: var(--accent); }

h1, h2, h3, h4 { 
  color: var(--text-main); 
  font-family: var(--font-heading); 
  font-weight: 700; 
  letter-spacing: -0.05em;
}

.container { max-width: 1200px; margin: 0 auto; padding: 0 20px; width: 100%; }

.site-header { 
  background: var(--bg-header); 
  border-bottom: 2px solid var(--border-color); 
  padding: 30px 0; 
}

.header-top { display: flex; justify-content: space-between; align-items: center; max-width: 1200px; margin: 0 auto; padding: 0 20px;}

.logo { font-size: 2.5rem; color: var(--accent); font-family: var(--font-heading); font-weight: 700; text-transform: lowercase; }

.nav-links { display: flex; gap: 30px; margin-top: 0; flex-wrap: wrap; justify-content: center; }

.nav-links a { font-weight: 700; text-transform: lowercase; font-size: 1rem; border: 1px solid var(--border-color); padding: 8px 16px; border-radius: var(--radius); }

.bottom-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 30px; margin: 60px 0; }

.post-thumb-card { 
  background: var(--bg-card); 
  padding: 30px; 
  border: 1px solid var(--border-color); 
  border-radius: var(--radius); 
  box-shadow: none; 
  display: flex; 
  flex-direction: column; 
  justify-content: space-between; 
  min-height: 250px; 
  transition: 0.4s; 
}

.post-thumb-card:hover { transform: scale(1.02); border-color: var(--accent); box-shadow: var(--shadow-sm); }

.cat-badge { 
  background: transparent; 
  color: var(--accent); 
  border: 1px solid var(--accent);
  padding: 4px 12px; 
  font-size: 0.7rem; 
  text-transform: uppercase; 
  display: inline-block; 
  margin-bottom: 20px; 
  border-radius: 50px; 
  font-weight: bold;
}

.post-thumb-title { font-size: 1.5rem; line-height: 1.2; color: #fff; }

.post-container { 
  max-width: 800px; 
  margin: 60px auto; 
  background: var(--bg-card); 
  padding: 60px; 
  border: 1px solid var(--border-color); 
  border-radius: var(--radius); 
}

.post-h1 { font-size: 3rem; margin-bottom: 30px; color: var(--accent); }

.post-meta-info { display: flex; align-items: center; gap: 20px; margin-bottom: 40px; border-top: 1px solid var(--border-color); padding-top: 30px; }

.post-meta-info img { width: 60px; height: 60px; border-radius: 12px; object-fit: cover; border: 2px solid var(--accent); }

.post-content { font-size: 1.2rem; line-height: 1.7; }

.post-content h2 { margin: 50px 0 25px; font-size: 2rem; color: var(--accent); }

.post-content p { margin-bottom: 25px; }

.post-content ul { margin: 0 0 25px 25px; }

.post-content a { color: var(--accent); text-decoration: none; border-bottom: 1px solid var(--accent); }

.pagination { display: flex; justify-content: center; gap: 15px; margin: 60px 0; }

.page-link { width: 50px; height: 50px; display: flex; align-items: center; justify-content: center; background: var(--bg-card); border: 1px solid var(--border-color); font-weight: bold; border-radius: var(--radius); }

.page-link.active { background: var(--accent); color: #000; border-color: var(--accent); }

.site-footer { background: var(--bg-header); padding: 60px 0; border-top: 2px solid var(--border-color); text-align: center; margin-top: auto; }
